	queue := []item{{n, nil}}
	for len(queue) > 0 {
		it := queue[0]
		queue = queue[1:]
		for i, c := range it.n.RawChildren {
			if c == nil {
				continue
			}
			path := append(append([]int{}, it.path...), i)
			if c == x {
				return path, true
			}
			if c.shape() == shapeTuple && c.Rule() == "" {
				queue = append(queue, item{c, path})
			}
		}
	}
	return nil, false
